<section class="page-heading"><div><p class="eyebrow">VALISE VIRTUELLE</p><h1><?= e($trip['name']??'Préparer un voyage') ?></h1><p class="subheading"><?= e($trip['destination']??'Sélectionnez vos affaires et les tenues prévues.') ?></p></div><?php if($trip): ?><form method="post" action="<?= e(url('trip-delete')) ?>" data-confirm="Supprimer ce voyage et sa liste de valise ?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($trip['id']) ?>"><button class="button danger">Supprimer le voyage</button></form><?php endif; ?></section>
<?php if($trip): ?><section class="form-panel packing-panel"><p class="eyebrow">LISTE DE PRÉPARATION</p><h2><?= count($selected) ?> article<?= count($selected)>1?'s':'' ?> à emporter</h2><?php if(!$selected): ?><p class="subheading">Ajoutez des vêtements ou des tenues dans le formulaire ci-dessous.</p><?php else: foreach($selected as $item): ?><div class="packing-row"><div><?php if($item['image_path']): ?><img src="<?= e(APP_BASE_URL.'/'.$item['image_path']) ?>" alt=""><?php endif; ?></div><span><b><?= e($item['name']) ?></b><small><?= e($item['label_name']) ?> · Quantité <?= e($item['quantity']) ?></small></span><form method="post" action="<?= e(url('trip-packed')) ?>"><?= csrf_field() ?><input type="hidden" name="trip_id" value="<?= e($trip['id']) ?>"><input type="hidden" name="clothing_id" value="<?= e($item['clothing_id']) ?>"><input type="hidden" name="packed" value="<?= $item['packed']?0:1 ?>"><button class="pack-check <?= $item['packed']?'checked':'' ?>" aria-label="<?= $item['packed']?'Décocher':'Marquer emballé' ?>"><?= $item['packed']?'✓':'○' ?></button></form></div><?php endforeach; endif; ?></section><?php endif; ?>
<section class="form-panel"><h2><?= $trip?'Modifier le voyage et sa valise':'Créer un voyage' ?></h2><form method="post" action="<?= e(url('trip-save')) ?>"><?= csrf_field() ?><?php if($trip): ?><input type="hidden" name="id" value="<?= e($trip['id']) ?>"><?php endif; ?><div class="form-row"><label>Nom *<input name="name" required maxlength="120" value="<?= e($trip['name']??'') ?>" placeholder="Ex. Séjour à Paris"></label><label>Destination<input name="destination" value="<?= e($trip['destination']??'') ?>"></label></div><div class="form-row"><label>Départ<input type="date" name="start_date" required value="<?= e($trip['start_date']??'') ?>"></label><label>Retour<input type="date" name="end_date" required value="<?= e($trip['end_date']??'') ?>"></label></div><label>Description<textarea name="description" rows="2"><?= e($trip['description']??'') ?></textarea></label><label>Notes<textarea name="notes" rows="2"><?= e($trip['notes']??'') ?></textarea></label><div class="form-row"><fieldset class="multi-select"><legend>Tenues prévues</legend><?php foreach($outfits as $outfit): ?><label><input type="checkbox" name="outfits[]" value="<?= e($outfit['id']) ?>" <?= in_array((int)$outfit['id'],$selectedOutfits,true)?'checked':'' ?>> <?= e($outfit['name']) ?></label><?php endforeach; ?></fieldset><fieldset class="multi-select"><legend>Vêtements à emporter</legend><?php $selectedIds=array_map('intval',array_column($selected,'clothing_id'));$selectedQty=[];foreach($selected as $s)$selectedQty[(int)$s['clothing_id']]=(int)$s['quantity'];foreach($clothes as $item): ?><label class="trip-item-choice"><span><input type="checkbox" name="items[]" value="<?= e($item['id']) ?>" <?= in_array((int)$item['id'],$selectedIds,true)?'checked':'' ?>> <?= e($item['name']) ?> · <?= e($item['label_name']) ?></span><input type="number" name="quantity[<?= e($item['id']) ?>]" min="1" max="99" value="<?= e($selectedQty[(int)$item['id']]??1) ?>" aria-label="Quantite pour <?= e($item['name']) ?>"></label><?php endforeach; ?></fieldset></div><button class="button primary">Enregistrer la valise <span>→</span></button></form></section>
